CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users(user_id SERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','admin')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INT NOT NULL REFERENCES users ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS student_profiles(user_id INT PRIMARY KEY REFERENCES users ON DELETE CASCADE,age INT NOT NULL CHECK(age BETWEEN 1 AND 100),course TEXT NOT NULL,cgpa NUMERIC NOT NULL CHECK(cgpa BETWEEN 0 AND 10),income NUMERIC NOT NULL CHECK(income>=0),state TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schemes(scheme_id SERIAL PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL,scheme_type TEXT NOT NULL CHECK(scheme_type IN ('scholarship','government_scheme')),description TEXT NOT NULL,min_age INT DEFAULT 16,max_age INT DEFAULT 35,max_income NUMERIC NOT NULL CHECK(max_income>=0),min_cgpa NUMERIC DEFAULT 0,course TEXT DEFAULT 'Any',state TEXT DEFAULT 'Any',category TEXT DEFAULT 'Any',deadline DATE NOT NULL,is_active BOOLEAN DEFAULT TRUE,updated_at TIMESTAMPTZ DEFAULT NOW(),CHECK(min_age<=max_age));
CREATE TABLE IF NOT EXISTS eligibility_criteria(criteria_id SERIAL PRIMARY KEY,scheme_id INT NOT NULL REFERENCES schemes ON DELETE CASCADE,field_name TEXT NOT NULL CHECK(field_name IN ('age','income','cgpa')),operator TEXT NOT NULL CHECK(operator IN ('>=','<=')),criteria_value NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS required_documents(document_id SERIAL PRIMARY KEY,scheme_id INT NOT NULL REFERENCES schemes ON DELETE CASCADE,document_name TEXT NOT NULL,is_mandatory BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS scheme_faqs(faq_id SERIAL PRIMARY KEY,scheme_id INT NOT NULL REFERENCES schemes ON DELETE CASCADE,question TEXT NOT NULL,answer TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(application_id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users ON DELETE CASCADE,scheme_id INT NOT NULL REFERENCES schemes ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('saved','applied')),applied_at TIMESTAMPTZ,updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,scheme_id));
CREATE TABLE IF NOT EXISTS scheme_embeddings(scheme_id INT PRIMARY KEY REFERENCES schemes ON DELETE CASCADE,content_text TEXT NOT NULL,embedding VECTOR(384) NOT NULL);
CREATE TABLE IF NOT EXISTS query_logs(log_id SERIAL PRIMARY KEY,user_id INT REFERENCES users ON DELETE SET NULL,query_text TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_embedding ON scheme_embeddings USING hnsw(embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_deadline ON schemes(deadline);
CREATE OR REPLACE FUNCTION touch_updated() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at=NOW(); RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER touch_scheme BEFORE UPDATE ON schemes FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE TRIGGER touch_application BEFORE UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE VIEW v_scheme_application_stats AS SELECT s.scheme_id,s.name,COUNT(a.application_id) FILTER(WHERE status='saved') AS saved_count,COUNT(a.application_id) FILTER(WHERE status='applied') AS applied_count FROM schemes s LEFT JOIN applications a USING(scheme_id) GROUP BY s.scheme_id;
CREATE OR REPLACE FUNCTION eligible(p_user INT) RETURNS SETOF schemes LANGUAGE sql STABLE AS $$ SELECT s.* FROM schemes s JOIN student_profiles p ON p.user_id=p_user WHERE s.is_active AND s.deadline>=CURRENT_DATE AND p.age BETWEEN s.min_age AND s.max_age AND p.income<=s.max_income AND p.cgpa>=s.min_cgpa AND (s.course='Any' OR s.course=p.course) AND (s.state='Any' OR s.state=p.state) AND (s.category='Any' OR s.category=p.category) AND NOT EXISTS(SELECT 1 FROM eligibility_criteria e WHERE e.scheme_id=s.scheme_id AND NOT(CASE e.field_name WHEN 'age' THEN p.age WHEN 'income' THEN p.income WHEN 'cgpa' THEN p.cgpa END IS NOT NULL AND CASE e.operator WHEN '>=' THEN CASE e.field_name WHEN 'age' THEN p.age WHEN 'income' THEN p.income ELSE p.cgpa END >= e.criteria_value ELSE CASE e.field_name WHEN 'age' THEN p.age WHEN 'income' THEN p.income ELSE p.cgpa END <= e.criteria_value END)); $$;
-- Database authorization: privileged mutations are guarded by the authenticated
-- role passed inside the server-owned transaction; clients cannot choose it.
CREATE OR REPLACE FUNCTION require_admin(p_user INT) RETURNS VOID AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM users WHERE user_id=p_user AND role='admin') THEN RAISE EXCEPTION 'Admin role required'; END IF; END; $$ LANGUAGE plpgsql;
